css:
.ui-root { --font-script: 'Anthropology', 'Great Vibes', cursive; --font-ui: 'Montserrat', sans-serif; --font-menu: 'Feminine', 'Raleway', 'Montserrat', sans-serif;
  --font-menu-body: 'Brooklyn', 'Raleway', 'Montserrat', sans-serif; --font-tech: 'Orbitron', sans-serif;
  --lavender: #cab0fa; --lavender-pale: #f1e8fe; --lilac-grey: #b9aec4; --cream: #f3e4c6; --champagne: #d8c6a2; --gold: #ffc248; }

.mm { background: radial-gradient(ellipse at 50% 40%, rgba(40,10,48,.55), rgba(6,1,8,.94) 70%); backdrop-filter: blur(6px); -webkit-backdrop-filter: blur(6px); }
.mm-title { --title-size: min(18.5vh, 11.5vw); top: 39% !important; z-index: 0; }
.mm-title::before { content: ''; position: absolute; left: 50%; top: 50%; width: min(64vh, 40vw); height: 118%; translate: -50% -50%; border-radius: 18px;
  background: rgba(26,8,28,.35); box-shadow: 0 0 40px 24px rgba(26,8,28,.35); z-index: -1; }
.mm-script { font: 400 calc(var(--title-size) - 2px)/1 var(--font-script); color: transparent; -webkit-text-stroke: 1.2px #f1eaff;
  filter: drop-shadow(0 0 1px rgba(240,228,255,.7)) drop-shadow(0 0 5px rgba(170,120,255,.6)) drop-shadow(0 0 16px rgba(120,60,220,.35)); }
.mm-sub { font: 400 calc(var(--title-size) * .6 - 2px)/1 var(--font-script); letter-spacing: .34em; margin: .02em 0 0 .34em; color: transparent; -webkit-text-stroke: 1px #f1eaff;
  filter: drop-shadow(0 0 1px rgba(240,228,255,.7)) drop-shadow(0 0 4px rgba(170,120,255,.6)) drop-shadow(0 0 12px rgba(120,60,220,.35)); }
.mm-list { top: 63% !important; width: 90%; max-width: 1000px; }
.mm-row { grid-template-columns: 1fr auto 1fr !important; align-items: center; gap: 20px; min-height: 40px; padding: 5px 0; background: none !important; }
.mm-btn { font: 400 calc(.75rem - 2px) var(--font-menu); letter-spacing: .42em; text-transform: uppercase; white-space: nowrap; text-align: center;
  color: transparent; background: linear-gradient(90deg, #e2dbec 0%, #cfc7da 52%, #6b6376 100%); -webkit-background-clip: text; background-clip: text; transition: all .3s; }
.mm-row.is-focus .mm-btn { background: none; color: #fff; text-shadow: 0 0 8px rgba(255,255,255,.85); }
.mm-desc, .mm-key { opacity: 0; transition: opacity .2s; font: 400 calc(.65rem - 2px) var(--font-menu-body); color: #e8e2f0; white-space: nowrap; }
.mm-row.is-focus .mm-desc, .mm-row.is-focus .mm-key { opacity: 1; }
.mm-desc { justify-self: end; min-width: 190px; padding: 2px 26px 2px 24px; text-align: center; position: relative;
  background: linear-gradient(90deg, rgba(30,6,40,0) 0%, rgba(34,8,46,.92) 18%, rgba(34,8,46,.95) 100%); }
.mm-desc::after { content: '▶'; position: absolute; right: 8px; color: #f4eeff; font-size: calc(.55rem - 2px); top: 50%; translate: 0 -50%; }
.mm-key { justify-self: start; min-width: 76px; text-align: center; padding: 3px 12px; color: #ece6f6; background: #170c20; border: 2.5px solid #9a85c8; border-radius: 20px;
  box-shadow: 0 0 8px rgba(154,133,200,.7), inset 0 0 6px rgba(154,133,200,.35); }

.ui-root { --font-script: 'Anthropology', 'Great Vibes', cursive; --font-ui: 'Montserrat', sans-serif; --font-menu: 'Feminine', 'Raleway', 'Montserrat', sans-serif;
  --font-menu-body: 'Brooklyn', 'Raleway', 'Montserrat', sans-serif; --font-tech: 'Orbitron', sans-serif;
  --lavender: #cab0fa; --lavender-pale: #f1e8fe; --lilac-grey: #b9aec4; --cream: #f3e4c6; --champagne: #d8c6a2; --gold: #ffc248; }

.pm { padding: 24px 7% 24px 3%; gap: 4vw; justify-content: space-between !important;
  background: linear-gradient(90deg, rgba(20,4,10,.25) 0%, rgba(14,3,12,.55) 45%, rgba(10,2,10,.93) 70%, rgba(8,1,8,.96) 100%),
    radial-gradient(ellipse 60% 70% at 20% 40%, rgba(120,30,10,.18), transparent 70%);
  backdrop-filter: blur(9px) saturate(1.25); -webkit-backdrop-filter: blur(9px) saturate(1.25); }
.pm-left { width: min(380px, 40vw); flex-shrink: 0; margin-top: 8vh; }
.pm-right { width: min(520px, 46vw); align-self: center; }
.pm-block { padding: 7px 12px; border-left: 2px solid rgba(255,255,255,.1); background: linear-gradient(90deg, rgba(20,6,26,.55), transparent); }
.pm-block.story { border-left-color: var(--lavender); } .pm-block.optional { border-left-color: rgba(120,220,205,.6); } .pm-block.side { border-left-color: var(--gold); }
.pm-block-label { font: 600 7px var(--font-ui); color: var(--champagne); letter-spacing: 2.5px; text-transform: uppercase; }
.pm-block-text { font: 400 10px/1.35 var(--font-ui); color: #e6dff0; }
.pm-title { font-family: var(--font-script); font-size: calc(3.4rem - 2px); color: var(--lavender-pale); text-align: center; margin-bottom: 26px; padding-bottom: 14px;
  text-shadow: 0 0 18px rgba(202,176,250,.55), 0 0 2px rgba(255,255,255,.6); border-bottom: 1px solid;
  border-image: linear-gradient(90deg, transparent, rgba(216,198,162,.55), rgba(255,255,255,.6), rgba(216,198,162,.55), transparent) 1; }
.pm-item { background: none !important; font: 400 calc(.74rem - 2px) var(--font-ui); letter-spacing: 4px; text-transform: uppercase; color: var(--lilac-grey);
  padding: 10px 24px; position: relative; z-index: 0; transition: color .25s ease; border-radius: 0; }
.pm-item.is-hover { color: #fff; }
.pm-item.is-focus { color: #120818; font-weight: 700; }
.pm-item::before { content: ''; position: absolute; left: -2%; right: -2%; top: 50%; translate: 0 -50%; height: 32px; border-radius: 16px; z-index: -1; opacity: 0; transition: opacity .2s;
  background: linear-gradient(90deg, transparent 0%, rgba(176,150,210,.7) 12%, #f2ecf4 40%, #f2ecf4 60%, rgba(176,150,210,.7) 88%, transparent 100%); box-shadow: 0 0 22px rgba(202,176,250,.35); }
.pm-item.is-focus::before { opacity: 1; }
.pm-item.is-inactive { opacity: .32; }
.ui-root[data-ui-open~="pause.settings"] .pm-nav, .ui-root[data-ui-open~="pause.saves"] .pm-nav { visibility: hidden; }

.ui-root { --font-script: 'Anthropology', 'Great Vibes', cursive; --font-ui: 'Montserrat', sans-serif; --font-menu: 'Feminine', 'Raleway', 'Montserrat', sans-serif;
  --font-menu-body: 'Brooklyn', 'Raleway', 'Montserrat', sans-serif; --font-tech: 'Orbitron', sans-serif;
  --lavender: #cab0fa; --lavender-pale: #f1e8fe; --lilac-grey: #b9aec4; --cream: #f3e4c6; --champagne: #d8c6a2; --gold: #ffc248; }

.pm-page { padding: 24px 7% 24px 3%; }
.pm-page-panel { width: min(520px, 46vw); margin-top: calc(3.4rem + 54px); max-height: 74vh; overflow-y: auto; }
.set-section { font: 600 calc(.6rem - 2px) var(--font-ui); letter-spacing: 4px; color: var(--champagne); text-transform: uppercase; text-align: right; margin-top: 10px; }
.set-row { padding: 8px 16px !important; border-radius: 4px; background: none !important; align-items: center; transition: background .2s; }
.set-row.is-focus { background: rgba(255,255,255,.05) !important; }
.set-row .ui-label { font: 500 calc(.75rem - 2px) var(--font-ui); letter-spacing: 2px; text-transform: uppercase; color: var(--lilac-grey); }
.set-row.is-focus .ui-label { color: var(--lavender-pale); }
.set-row .ui-value { font: 600 calc(.64rem - 2px) var(--font-ui); letter-spacing: 1.5px; color: var(--lavender-pale); padding: 4px 14px; min-width: 60px; text-align: center;
  border: 1px dotted rgba(202,176,250,.5); border-radius: 12px; transition: all .2s; }
.set-row.is-focus .ui-value { border-color: var(--lavender); color: #fff; box-shadow: 0 0 10px rgba(202,176,250,.35); }
.set-row.ui-toggle .ui-value { color: rgba(185,174,196,.5); border-color: rgba(185,174,196,.18); }
.set-row.ui-toggle.is-active .ui-value { color: #1b0d2e; border: 1px solid rgba(255,255,255,.7); background: radial-gradient(ellipse 70% 120% at 50% 50%, #f2ecf4 0%, var(--lavender) 90%); }
.set-back { align-self: center; margin-top: 14px; background: none !important; font: 500 calc(.8rem - 2px) var(--font-ui); letter-spacing: 3px; text-transform: uppercase; color: #888; padding: 12px 30px; }
.set-back.is-focus { color: #fff; text-shadow: 0 0 8px rgba(255,255,255,.7); }
.ui-root:not([data-ui-open~="pause"]) .pm-page { background: rgba(8,1,8,.86); backdrop-filter: blur(9px); -webkit-backdrop-filter: blur(9px); }
.ui-root:not([data-ui-open~="pause"]) .pm-page-panel { margin: auto; }

.ui-root { --font-script: 'Anthropology', 'Great Vibes', cursive; --font-ui: 'Montserrat', sans-serif; --font-menu: 'Feminine', 'Raleway', 'Montserrat', sans-serif;
  --font-menu-body: 'Brooklyn', 'Raleway', 'Montserrat', sans-serif; --font-tech: 'Orbitron', sans-serif;
  --lavender: #cab0fa; --lavender-pale: #f1e8fe; --lilac-grey: #b9aec4; --cream: #f3e4c6; --champagne: #d8c6a2; --gold: #ffc248; }

.save-slots .ui-empty { font: italic 400 calc(.68rem - 2px) var(--font-ui); color: rgba(185,174,196,.55); text-align: center; padding: 18px 0; }
.save-slot { background: linear-gradient(90deg, rgba(20,6,26,.55), transparent) !important; border-left: 2px solid var(--lavender); border-radius: 0; text-align: left;
  font: 500 calc(.72rem - 2px) var(--font-ui); letter-spacing: 2px; color: #e6dff0; }
.save-slot.is-focus { background: linear-gradient(90deg, rgba(202,176,250,.25), transparent) !important; color: #fff; }
.ui-root:not([data-ui-open~="pause"]) .pm-page { background: rgba(8,1,8,.86); backdrop-filter: blur(9px); -webkit-backdrop-filter: blur(9px); }
.ui-root:not([data-ui-open~="pause"]) .pm-page-panel { margin: auto; }

.ui-root :is(.df-move-zone, .df-aim-zone) { display: none; }
body.touch .ui-root[data-ui-top="hud"] :is(.df-move-zone, .df-aim-zone) { display: block; position: absolute; pointer-events: auto; touch-action: none; }
.df-move-zone { left: 0; bottom: 0; width: 50%; height: 55%; }
.df-aim-zone { right: max(44px, calc(env(safe-area-inset-right) + 32px)); bottom: max(44px, calc(env(safe-area-inset-bottom) + 32px)); width: 100px; height: 100px; }
.df-stick { position: absolute; border-radius: 50%; background: rgba(20, 0, 10, .4); box-shadow: 0 4px 15px rgba(0, 0, 0, .5); backdrop-filter: blur(2px); pointer-events: none; }
.ui-root .df-move-base { display: none; position: fixed; width: 128px; height: 128px; }
.df-aim-base { left: 50%; top: 50%; translate: -50% -50%; width: 80px; height: 80px; }
.df-stick-knob { position: absolute; top: 50%; left: 50%; width: 36px; height: 36px; border-radius: 50%; pointer-events: none;
  transform: translate(calc(-50% + var(--lx, 0px)), calc(-50% + var(--ly, 0px)));
  background: radial-gradient(circle at 35% 35%, #fffbf2 0%, #e8dcc0 40%, #c4a980 100%);
  box-shadow: inset 2px 2px 3px #fff, inset -2px -2px 4px rgba(100, 80, 60, .4), 0 5px 10px rgba(0, 0, 0, .5); }
.df-aim-ring, .df-aim-band { position: absolute; left: 50%; top: 50%; translate: -50% -50%; border-radius: 50%; pointer-events: none; }
.df-aim-ring { width: 84px; height: 84px; border: 1.5px solid rgba(232, 194, 122, .35); box-shadow: 0 0 6px rgba(232, 194, 122, .15); }
.df-aim-band { width: 128px; height: 128px; border: 3px solid currentColor; color: rgba(232, 194, 122, .55); opacity: 0; transition: opacity .15s, color .12s; }
.df-aim-zone[data-stick-state]:not([data-stick-state="idle"]) .df-aim-band { opacity: 1; }
.df-aim-zone[data-stick-state="firing"] :is(.df-aim-ring,.df-aim-band) { color: #ffd68c; border-color: #ffd68c; box-shadow: 0 0 14px rgba(255, 190, 90, .75); }
.df-aim-zone[data-stick-state="armed"] :is(.df-aim-ring,.df-aim-band) { color: #c8aaff; border-color: #c8aaff; box-shadow: 0 0 14px rgba(170, 130, 255, .8); animation: df-aim-armed .8s ease-in-out infinite; }
@keyframes df-aim-armed { 50% { box-shadow: 0 0 22px #aa82ff; } }
@media (prefers-reduced-motion: reduce) { .df-aim-zone[data-stick-state="armed"] :is(.df-aim-ring,.df-aim-band) { animation: none; } }

.ui-root { --font-script: 'Anthropology', 'Great Vibes', cursive; --font-ui: 'Montserrat', sans-serif; --font-menu: 'Feminine', 'Raleway', 'Montserrat', sans-serif;
  --font-menu-body: 'Brooklyn', 'Raleway', 'Montserrat', sans-serif; --font-tech: 'Orbitron', sans-serif;
  --lavender: #cab0fa; --lavender-pale: #f1e8fe; --lilac-grey: #b9aec4; --cream: #f3e4c6; --champagne: #d8c6a2; --gold: #ffc248; }

.hud-health { width: 200px; height: 12px; border-radius: 0; background: rgba(30,5,5,.95); color: #8b0000; }
.hud-health .ui-fill { background: linear-gradient(90deg, #3a0000, #6b0000, #8b0000); box-shadow: inset 0 1px 0 rgba(255,100,100,.15); border-radius: 0; transition: width .2s ease-out; }
.hud-pause { width: 44px; height: 44px; padding: 0 !important; border-radius: 50% !important; display: flex; align-items: center; justify-content: center;
  background: rgba(20,0,10,.4) !important; border: 1px solid rgba(255,255,255,.2); color: #fff; font-size: calc(1.2rem - 2px); }
.hud-pause.is-hover { background: rgba(60,10,40,.6) !important; }
.hud-time { font: 500 calc(1.2rem - 2px) var(--font-tech); color: #fff; text-shadow: 0 0 5px #fff; letter-spacing: 2px; }
.hud-money { font: 400 calc(.9rem - 2px) var(--font-ui); color: #ffd700; text-shadow: 0 0 5px #ffd700; }
.hud-location { font: 400 calc(1.3rem - 2px) var(--font-script); color: #fff; text-shadow: 0 2px 6px rgba(0,0,0,.8), 0 0 15px rgba(164,105,255,.3); }
